qwen_base/BASE16_agentic_grep_04fd33ea.gt_sparql:
PREFIX eno: <http://example.org/ontology/energy#>
SELECT DISTINCT ?field ?fieldName WHERE {
    ?field a eno:Deposit .
    ?company a eno:Company .
