qwen_syn/SYN10_agentic_grep_2529a568.final_sparql:
PREFIX bsbm: <http://www4.wiwiss.fu-berlin.de/bizer/bsbm/v01/vocabulary/>

SELECT ?product ?price ?type
WHERE {
  {
    SELECT ?product ?price ("cheapest" AS ?type)
    WHERE {
      ?offer a bsbm:Offer ;
             bsbm:price ?price ;
             bsbm:product ?product .
    }
    ORDER BY ASC(?price)
    LIMIT 1
  }
  UNION
  {
    SELECT ?product ?price ("most_expensive" AS ?type)
    WHERE {
      ?offer a bsbm:Offer ;
             bsbm:price ?price ;
             bsbm:product ?product .
    }
    ORDER BY DESC(?price)
    LIMIT 1
  }
}

